// testTime is the fixed clock the tests run under so _stages/_provenance
// timestamps are deterministic (code-quality hermeticity).
var testTime = time.Date(2026, 7, 31, 12, 0, 0, 0, time.UTC)

// fakeSource is sdk.MetadataSource's second implementation (R8), injected via
// the metadataResolver seam. It is configurable per scenario: whether it applies,
// the metadata it contributes, and failure/namespace-violation modes. It mirrors
// what a real metadata_source plugin (tv-parser, T06) does — write sources.<id>
// from the incoming metadata.
type fakeSource struct {
	id           string
	applies      bool
	metadata     map[string]any
	domainErr    *metadatav1.Error // ConvertResult.Error (domain-level convert failure)
	mergeErr     error
	writeForeign bool      // malicious: also write sources.OTHER (namespace violation)
	order        *[]string // shared Match-call order (priority test)
}

func (f *fakeSource) Match(context.Context, *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	if f.order != nil {
		*f.order = append(*f.order, f.id)
	}
	return &metadatav1.MatchResult{Applies: f.applies}, nil
}
func (f *fakeSource) BuildRequest(context.Context, *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{}, nil
}
func (f *fakeSource) Convert(context.Context, *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	md, _ := structpb.NewStruct(f.metadata)
	return &metadatav1.ConvertResult{Metadata: md, Error: f.domainErr}, nil
}
func (f *fakeSource) Merge(_ context.Context, req *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	if f.mergeErr != nil {
		return nil, f.mergeErr
	}
	return &metadatav1.MergeResult{Document: wrapNamespace(f.id, req.GetIncoming(), f.writeForeign)}, nil
}

// wrapNamespace builds the MergeResult document a well-behaved plugin returns:
// sources.<pluginID> = incoming. When foreign is set it also writes sources.OTHER
// (the namespace-violation probe).
func wrapNamespace(pluginID string, incoming *structpb.Struct, foreign bool) *commonv1.MediaDocument {
	sources := map[string]any{}
	if incoming != nil {
		sources[pluginID] = incoming.AsMap()
	}
	if foreign {
		sources["OTHER"] = map[string]any{"poison": true}
	}
	data, _ := structpb.NewStruct(map[string]any{"sources": sources})
	return &commonv1.MediaDocument{Data: data}
}

// fakeRegistry resolves pluginIDs to fakes; an unknown id mirrors an unloaded
// plugin (the kinopoisk/tmdb Phase A case).
type fakeRegistry map[string]*fakeSource

func (r fakeRegistry) resolve(pluginID, capabilityID string) (sdk.MetadataSource, error) {
	if f, ok := r[pluginID]; ok {
		return f, nil
	}
	return nil, fmt.Errorf("plugin %q not loaded", pluginID)
}

func binding(pluginID string, priority int, enabled bool) module.MetadataSourceBinding {
	return module.MetadataSourceBinding{PluginID: pluginID, CapabilityID: "default", Priority: priority, Enabled: enabled}
}

// nested walks a document by keys, returning nil if any segment is absent or not
// a map. Keeps per-row assertions compact.
func nested(doc map[string]any, path ...string) any {
	var cur any = doc
	for _, p := range path {
		m, ok := cur.(map[string]any)
		if !ok {
			return nil
		}
		cur = m[p]
	}
	return cur
}

func stages(doc map[string]any) []map[string]any {
	s, _ := doc["_stages"].([]map[string]any)
	return s
}

// TestEnrich exercises the orchestrator end-to-end via the resolver seam: the
// serial priority-ordered chain, provenance/_view/_stages assembly (AC-5),
// namespace-violation reject+revert (AC-6), soft-fail furthest-valid state
// (AC-6/AC-7), and the cancelled-context hard failure (B8).
func TestEnrich(t *testing.T) {
	realNow := now
	now = func() time.Time { return testTime }
	defer func() { now = realNow }()

	type row struct {
		name       string
		sources    []module.MetadataSourceBinding
		fakes      fakeRegistry
		ctx        context.Context // nil -> background
		wantStatus string
		wantErr    bool
		check      func(t *testing.T, doc map[string]any, res Result)
	}

	tvMeta := map[string]any{"title": "Breaking Bad", "season": float64(1), "episode": float64(2)}

	rows := []row{
		{
			name:    "happy: one applying source -> enriched + provenance/view/stages",
			sources: []module.MetadataSourceBinding{binding("tv-parser", 1, true)},
			fakes:   fakeRegistry{"tv-parser": {id: "tv-parser", applies: true, metadata: tvMeta}},
			check: func(t *testing.T, doc map[string]any, res Result) {
				if nested(doc, "sources", "tv-parser", "title") != "Breaking Bad" {
					t.Fatalf("sources.tv-parser.title = %v, want Breaking Bad", nested(doc, "sources", "tv-parser", "title"))
				}
				if pid := nested(doc, "_provenance", "title", "plugin_id"); pid != "tv-parser" {
					t.Fatalf("_provenance.title.plugin_id = %v, want tv-parser", pid)
				}
				if v := nested(doc, "_view", "title", "value"); v != "Breaking Bad" {
					t.Fatalf("_view.title.value = %v, want Breaking Bad", v)
				}
				if src := nested(doc, "_view", "title", "source"); src != "tv-parser" {
					t.Fatalf("_view.title.source = %v, want tv-parser", src)
				}
				if len(stages(doc)) != 1 || stages(doc)[0]["status"] != "ok" {
					t.Fatalf("_stages = %+v, want 1 ok entry", stages(doc))
				}
				if res.Succeeded != 1 || res.Stages != 1 {
					t.Fatalf("Result = %+v, want Succeeded=1 Stages=1", res)
				}
			},
			wantStatus: statusEnriched,
		},
		{
			name:    "applies=false -> skipped stage, no namespace write, status new",
			sources: []module.MetadataSourceBinding{binding("tv-parser", 1, true)},
			fakes:   fakeRegistry{"tv-parser": {id: "tv-parser", applies: false}},
			check: func(t *testing.T, doc map[string]any, res Result) {
				if len(stages(doc)) != 1 || stages(doc)[0]["status"] != "skipped" {
					t.Fatalf("_stages = %+v, want 1 skipped entry", stages(doc))
				}
				if doc["sources"] != nil {
					t.Fatalf("sources written despite applies=false: %+v", doc["sources"])
				}
				if len(res.Warnings) != 0 {
					t.Fatalf("applies=false should not warn, got %v", res.Warnings)
				}
			},
			wantStatus: statusNew,
		},
		{
			name:    "two sources run in priority order",
			sources: []module.MetadataSourceBinding{binding("a", 2, true), binding("b", 1, true)},
			fakes:   fakeRegistry{"a": {id: "a", applies: true, metadata: map[string]any{"x": "A"}}, "b": {id: "b", applies: true, metadata: map[string]any{"y": "B"}}},
			check: func(t *testing.T, doc map[string]any, res Result) {
				if nested(doc, "sources", "a", "x") != "A" || nested(doc, "sources", "b", "y") != "B" {
					t.Fatalf("sources = %+v, want both a and b", doc["sources"])
				}
			},
			wantStatus: statusEnriched,
		},
		{
			name:    "namespace violation -> reject+revert+failed stage+soft-fail",
			sources: []module.MetadataSourceBinding{binding("tv-parser", 1, true)},
			fakes:   fakeRegistry{"tv-parser": {id: "tv-parser", applies: true, metadata: tvMeta, writeForeign: true}},
			check: func(t *testing.T, doc map[string]any, res Result) {
				if doc["sources"] != nil {
					t.Fatalf("namespace violation must revert sources, got %+v", doc["sources"])
				}
				if len(stages(doc)) != 1 || stages(doc)[0]["status"] != "failed" {
					t.Fatalf("_stages = %+v, want 1 failed entry", stages(doc))
				}
				if len(res.Warnings) != 1 {
					t.Fatalf("Warnings = %v, want 1 (the violation)", res.Warnings)
				}
			},
			wantStatus: statusPending, // began, the source failed, nothing succeeded
		},
		{
			name:    "convert domain error mid-chain -> soft-fail, upstream kept, furthest-valid",
			sources: []module.MetadataSourceBinding{binding("a", 1, true), binding("b", 2, true)},
			fakes: fakeRegistry{
				"a": {id: "a", applies: true, metadata: map[string]any{"x": "A"}},
				"b": {id: "b", applies: true, metadata: map[string]any{"y": "B"}, domainErr: &metadatav1.Error{Code: "parse_error", Message: "boom"}},
			},
			check: func(t *testing.T, doc map[string]any, res Result) {
				if nested(doc, "sources", "a", "x") != "A" {
					t.Fatalf("upstream source a must be kept, sources = %+v", doc["sources"])
				}
				if nested(doc, "sources", "b") != nil {
					t.Fatalf("failed source b must not write, sources.b = %v", nested(doc, "sources", "b"))
				}
				if len(res.Warnings) != 1 {
					t.Fatalf("Warnings = %v, want 1 (b's convert error)", res.Warnings)
				}
			},
			wantStatus: statusParsed, // a succeeded, b failed -> furthest valid
		},
		{
			name:    "unloaded source -> unavailable stage + warning, status new",
			sources: []module.MetadataSourceBinding{binding("kinopoisk", 1, true)},
			fakes:   fakeRegistry{}, // kinopoisk not loaded
			check: func(t *testing.T, doc map[string]any, res Result) {
				if len(stages(doc)) != 1 || stages(doc)[0]["status"] != "unavailable" {
					t.Fatalf("_stages = %+v, want 1 unavailable entry", stages(doc))
				}
				if len(res.Warnings) != 1 {
					t.Fatalf("Warnings = %v, want 1 (unavailable)", res.Warnings)
				}
			},
			wantStatus: statusNew,
		},
		{
			name:    "cancelled context -> hard failure, status failed, _error recorded",
			sources: []module.MetadataSourceBinding{binding("tv-parser", 1, true)},
			fakes:   fakeRegistry{"tv-parser": {id: "tv-parser", applies: true, metadata: tvMeta}},
			ctx:     cancelledContext(),
			check: func(t *testing.T, doc map[string]any, res Result) {
				if doc["_error"] == nil {
					t.Fatalf("cancelled context must record _error, doc = %+v", doc)
				}
			},
			wantStatus: statusFailed,
			wantErr:    true,
		},
	}

	for _, tc := range rows {
		t.Run(tc.name, func(t *testing.T) {
			ctx := tc.ctx
			if ctx == nil {
				ctx = context.Background()
			}
			var order []string
			for _, f := range tc.fakes {
				f.order = &order
			}
			doc := map[string]any{}
			out, status, res, err := enrichDoc(ctx, tc.fakes.resolve, module.Module{ID: "tv", MediaType: "tv", MetadataSources: tc.sources}, doc, &scannerv1.IdentifyResult{}, nil)
			if (err != nil) != tc.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tc.wantErr)
			}
			if status != tc.wantStatus {
				t.Fatalf("status = %q, want %q", status, tc.wantStatus)
			}
			if tc.name == "two sources run in priority order" && !reflect.DeepEqual(order, []string{"b", "a"}) {
				t.Fatalf("Match call order = %v, want [b a] (priority ascending)", order)
			}
			if tc.check != nil {
				tc.check(t, out, res)
			}
		})
	}
}

// TestNextState is the full state-machine table (INV-status-owner, B9): every
// legal transition yields the documented next status; every illegal transition
// returns a non-nil error (never persisted). The acceptance.md state machine is
// the authority.
func TestNextState(t *testing.T) {
	legal := []struct {
		from, want string
		ev         enrichEvent
	}{
		{statusNew, statusPending, evBegin},
		{statusNew, statusFailed, evFailed},
		{statusNew, statusDeleted, evDeleted},
		{statusPending, statusParsed, evParsed},
		{statusPending, statusEnriched, evEnriched},
		{statusPending, statusFailed, evFailed},
		{statusPending, statusDeleted, evDeleted},
		{statusParsed, statusPending, evBegin},
		{statusParsed, statusEnriched, evEnriched},
		{statusParsed, statusFailed, evFailed},
		{statusParsed, statusDeleted, evDeleted},
		{statusEnriched, statusFailed, evFailed},
		{statusEnriched, statusDeleted, evDeleted},
		{statusFailed, statusPending, evRetry},
		{statusFailed, statusDeleted, evDeleted},
		// B1 new transitions: async settlement, re-scan stale, rehydrate, and the
		// * --deleted--> soft-delete applied to the new live states (ready, stale).
		{statusEnriched, statusReady, evSettled},
		{statusNew, statusStale, evStale},
		{statusPending, statusStale, evStale},
		{statusParsed, statusStale, evStale},
		{statusEnriched, statusStale, evStale},
		{statusReady, statusStale, evStale},
		{statusFailed, statusStale, evStale},
		{statusStale, statusPending, evRehydrate},
		{statusStale, statusDeleted, evDeleted},
		{statusReady, statusDeleted, evDeleted},
	}
	for _, tc := range legal {
		got, err := nextState(tc.from, tc.ev)
		if err != nil || got != tc.want {
			t.Fatalf("nextState(%s,%s) = (%q,%v), want (%q,nil)", tc.from, tc.ev, got, err, tc.want)
		}
	}

	states := []string{statusNew, statusPending, statusParsed, statusEnriched, statusFailed, statusDeleted, statusReady, statusStale}
	events := []enrichEvent{evBegin, evParsed, evEnriched, evFailed, evRetry, evDeleted, evSettled, evStale, evRehydrate}
	legalSet := make(map[string]bool, len(legal))
	for _, tc := range legal {
		legalSet[tc.from+"|"+string(tc.ev)] = true
	}
	var illegal int
	for _, s := range states {
		for _, e := range events {
			if legalSet[s+"|"+string(e)] {
				continue
			}
			if _, err := nextState(s, e); err == nil {
				t.Fatalf("nextState(%s,%s) unexpectedly succeeded; want illegal-transition error", s, e)
			}
			illegal++
		}
	}
	if illegal == 0 {
		t.Fatal("no illegal transitions enumerated")
	}

	// B5: ready is terminal-success -- the enrichment events must not advance it.
	// (Covered by the loop above, but asserted explicitly as the named probe.)
	if _, err := nextState(statusReady, evParsed); err == nil {
		t.Fatalf("nextState(ready, parsed) unexpectedly succeeded; ready is terminal-success")
	}
}

// TestValidateNamespace is the namespace-invariant unit (architecture §3.3): the
// plugin may write ONLY sources.<its_own_plugin_id>. A foreign source namespace
// or any non-sources top-level key is rejected; the plugin's own namespace is
// unconstrained.
func TestValidateNamespace(t *testing.T) {
	doc := func(m map[string]any) *commonv1.MediaDocument {
		s, _ := structpb.NewStruct(m)
		return &commonv1.MediaDocument{Data: s}
	}
	tv := doc(map[string]any{"sources": map[string]any{"tv-parser": map[string]any{"title": "X"}}})
	foreignSrc := doc(map[string]any{"sources": map[string]any{"tv-parser": map[string]any{"title": "X"}, "OTHER": map[string]any{"p": 1}}})
	foreignTop := doc(map[string]any{"sources": map[string]any{"tv-parser": map[string]any{}}, "_view": map[string]any{"x": 1}})

	tests := []struct {
		name    string
		d       *commonv1.MediaDocument
		wantErr bool
	}{
		{name: "own namespace only", d: tv, wantErr: false},
		{name: "foreign source key rejected", d: foreignSrc, wantErr: true},
		{name: "foreign top-level key rejected", d: foreignTop, wantErr: true},
		{name: "nil document (no contribution)", d: nil, wantErr: false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := validateNamespace(tc.d, "tv-parser")
			if (err != nil) != tc.wantErr {
				t.Fatalf("validateNamespace err = %v, wantErr = %v", err, tc.wantErr)
			}
		})
	}
}

// cancelledContext returns an already-cancelled context (B8 hard-fail probe).
func cancelledContext() context.Context {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	return ctx
}
